// Generated by Fritz's EC551 PA2 backend; internal controller can be replaced
// with Ayla's FSM when integrated. Inputs are sampled at START.
// step_enable MUST be a debounced one-clock pulse, synchronous to clk.
module generated_system(
    input wire clk,
    input wire rst,
    input wire start,
    input wire step_enable,
    output reg busy,
    output reg done,
    output wire [1:0] step_debug,
    input wire [7:0] in_A,
    input wire [7:0] in_B,
    input wire [7:0] in_C,
    input wire [7:0] in_D,
    output wire [7:0] out_X,
    output wire [7:0] out_Y,
    output wire [7:0] out_Z,
    output wire [7:0] out_Q,
    output wire [7:0] fu_add_0_out,
    output wire [7:0] fu_add_1_out,
    output wire [7:0] fu_sub_0_out
);
  reg [1:0] step;
  assign step_debug = step;
  reg [7:0] input_latch_in_A;
  reg [7:0] input_latch_in_B;
  reg [7:0] input_latch_in_C;
  reg [7:0] input_latch_in_D;
  generated_datapath dp (
    .clk(clk), .rst(rst), .write_en(busy && step_enable), .step(step),
    .i_in_A(input_latch_in_A),
    .i_in_B(input_latch_in_B),
    .i_in_C(input_latch_in_C),
    .i_in_D(input_latch_in_D),
    .out_X(out_X),
    .out_Y(out_Y),
    .out_Z(out_Z),
    .out_Q(out_Q),
    .fu_add_0_out(fu_add_0_out),
    .fu_add_1_out(fu_add_1_out),
    .fu_sub_0_out(fu_sub_0_out)
  );
  always @(posedge clk) begin
    if (rst) begin
      busy <= 1'b0;
      done <= 1'b0;
      step <= 2'd0;
      input_latch_in_A <= 8'd0;
      input_latch_in_B <= 8'd0;
      input_latch_in_C <= 8'd0;
      input_latch_in_D <= 8'd0;
    end else if (start && !busy) begin
      done <= 1'b0;
      step <= 2'd0;
      input_latch_in_A <= in_A;
      input_latch_in_B <= in_B;
      input_latch_in_C <= in_C;
      input_latch_in_D <= in_D;
      busy <= 1'b1;
    end else if (busy && step_enable) begin
      if (step == 2'd2) begin
        busy <= 1'b0;
        done <= 1'b1;
      end else begin
        step <= step + 2'd1;
      end
    end
  end
endmodule
